const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=n=>n==null?'—':Number(n).toLocaleString('vi-VN',{maximumFractionDigits:1});
let state=null,version=0,user=null,view='overview',period={type:'month',value:10},editing=null,updating=null,editingAction=null,showArchive=false,busy=false,stale=false;
const roleNames={admin:'Quản trị',leader:'Cấp IID',manager:'Quản lý bộ phận',contributor:'Nhân viên',viewer:'Người xem'},modeNames={last:'Giá trị cuối kỳ',sum:'Cộng các tháng',average:'Trung bình các tháng'},planNames={annual:'Giữ mức năm',linear:'Lũy kế đều',monthly:'Chia đều 12 tháng'};
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500)}
async function req(url,method='GET',body){let r=await fetch(url,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let x=await r.json();if(!r.ok)throw Object.assign(Error(x.error||'Lỗi kết nối'),{status:r.status});return x}
async function sync(){try{let x=await req('/api/workspace');state=x.state?KPI.migrate(x.state):null;version=x.version;stale=false;render();toast('Đã tải dữ liệu mới nhất')}catch(e){toast(e.message)}}
async function mutate(op){if(busy){toast('Đang lưu, vui lòng chờ.');return false}if(stale){toast('Có thay đổi từ người khác. Hãy bấm Đồng bộ trước khi lưu.');return false}busy=true;try{let x=await req('/api/workspace','POST',{version,op});state=KPI.migrate(x.state);version=x.version;render();toast('Đã lưu vào kho chung');return true}catch(e){if(e.status===409)stale=true;toast(e.message);return false}finally{busy=false}}
const manage=k=>user&&(user.role==='admin'||user.role==='leader'&&k.level==='IID'||user.role==='manager'&&k.level!=='IID'&&k.team===user.team),write=k=>manage(k)||user?.role==='contributor'&&k.ownerEmail?.toLowerCase()===user.email;
const result=k=>KPI.measure(k,period),score=k=>result(k).score,titlePeriod=()=>period.type==='month'?`Tháng ${period.value}/2027`:`Quý ${period.value}/2027`;
const fillClass=n=>n==null?'':n<80?'bad':n<100?'warn':'';
const isOverdue=a=>a.status!=='Hoàn tất'&&a.due<new Date().toISOString().slice(0,10);
function head(title,desc,create=false){return `<div class="titlebar"><div><div class="eyebrow">KHO KPI CHUNG · ${esc(titlePeriod())} · PHIÊN BẢN ${version}</div><h1>${title}</h1><p>${desc}</p></div>${create&&['admin','leader','manager'].includes(user.role)?'<button class="primary" onclick="openEditor()">+ Tạo KPI mới</button>':''}</div>`}
function badge(k,p=period){let n=KPI.measure(k,p).score;return `<span class="badge ${n==null||n<100?'warn':''} ${n!=null&&n<80?'bad':''}">${n==null?'Chưa đủ dữ liệu':n>=100?'Đạt mục tiêu':n<80?'Cần chú ý':'Đang theo dõi'}</span>`}
function warning(){return Object.values(KPI.groups(state.kpis)).filter(ks=>Math.abs(ks.reduce((s,k)=>s+k.weight,0)-100)>.01).map(ks=>`<div class="alert"><strong>${esc(KPI.label(ks))}</strong>: tổng trọng số hiện tại là ${num(ks.reduce((s,k)=>s+k.weight,0))}%, cần điều chỉnh về đúng 100% để tính điểm.</div>`).join('')}
function rows(ks){return !ks.length?'<div class="empty">Không có KPI phù hợp với bộ lọc hiện tại.</div>':`<div class="tablewrap"><table><thead><tr><th>KPI / NGƯỜI PHỤ TRÁCH</th><th>CẤP / BỘ PHẬN</th><th>TRỌNG SỐ</th><th>MỤC TIÊU KỲ</th><th>KẾT QUẢ</th><th>HOÀN THÀNH</th><th>THAO TÁC</th></tr></thead><tbody>${ks.map(k=>{let r=result(k),note=period.type==='month'?k.updates[period.value]?.note:'';return `<tr><td><strong>${esc(k.name)}</strong><small>${esc(k.owner)} · ${esc(k.ownerEmail||'Chưa gán email')}</small><small>Nguồn: ${esc(k.source)}</small></td><td><span class="badge neutral">${esc(k.level)}</span><small>${esc(k.team)}</small></td><td><strong>${num(k.weight)}%</strong></td><td>${num(r.target)} ${esc(k.unit)}<small>${esc(modeNames[k.mode])} · ${k.direction==='down'?'↓ Giảm tốt':'↑ Tăng tốt'}</small></td><td><strong>${num(r.actual)}</strong> ${r.actual!=null?esc(k.unit):''}<small>${r.coverage}/${r.total} tháng có dữ liệu${note?' · '+esc(note.slice(0,36)):''}</small></td><td>${badge(k)}<small><strong>${num(r.score)}%</strong></small><div class="track"><div class="fill ${fillClass(r.score)}" style="width:${Math.min(100,r.score||0)}%"></div></div></td><td>${write(k)?`<button onclick="openUpdate(${JSON.stringify(k.id).replaceAll('"','&quot;')})">Cập nhật</button>`:''}${manage(k)?`<button onclick="openEditor(${JSON.stringify(k.id).replaceAll('"','&quot;')})">Sửa</button><button class="danger" onclick="removeKpi(${JSON.stringify(k.id).replaceAll('"','&quot;')})">Lưu trữ</button>`:''}</td></tr>`}).join('')}</tbody></table></div>`}
function render(){
  applyMenus();if(view==='account'||user?.mustChange){renderAccount();return}if(view==='members'){renderMembers();return}
  document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(!user)return;
  if(!state){$('#app').innerHTML=head('Khởi tạo kho KPI chung','Chọn dữ liệu để bắt đầu. Dữ liệu cũ trên trình duyệt được giữ lại.')+(user.role==='admin'?`<div class="guidegrid"><div class="panel"><h2>Chuyển dữ liệu phiên bản cũ</h2><p>Dùng dữ liệu KPI đang lưu trên trình duyệt này để tạo kho chung.</p><button onclick="initialize('local')">Chuyển dữ liệu cũ</button></div><div class="panel"><h2>Bắt đầu mới</h2><p>Kho trống để nhập KPI thực tế, hoặc bộ KPI minh họa có sẵn.</p><button class="primary" onclick="initialize('empty')">Tạo kho trống</button> <button onclick="initialize('sample')">Dùng dữ liệu mẫu</button></div></div>`:'<div class="panel">Quản trị cần khởi tạo kho chung trước.</div>');return}
  let ks=state.kpis,groups=KPI.groups(ks),primary=KPI.primaryGroup(groups,user),primaryScore=primary?totalScore(primary,period):null,overdueCount=state.actions.filter(isOverdue).length;
  if(view==='overview')$('#app').innerHTML=head('Tổng quan hiệu suất','Cùng một nguồn dữ liệu. Rõ mục tiêu, rõ trách nhiệm.',true)+`<div class="hero"><div><div class="eyebrow">IID · WORKSPACE 2027</div><h2>Mỗi đóng góp kết nối với mục tiêu chung.</h2><p>${esc(user.name||user.email)} (${esc(user.email)}) · ${esc(roleNames[user.role])}${user.team?' · '+esc(user.team):''}</p></div><div class="art">↗</div></div><div class="stats"><div class="card"><small>ĐIỂM TRONG PHẠM VI</small><div class="number">${num(primaryScore)}%</div><p>${primary?esc(KPI.label(primary)):'Chưa có nhóm KPI'} · Trần 120%</p></div><div class="card"><small>KPI ĐANG QUẢN LÝ</small><div class="number">${ks.length}</div><p>${Object.keys(groups).length} nhóm mục tiêu${state.archive?.length?` · ${state.archive.length} lưu trữ`:''}</p></div><div class="card"><small>CÓ ĐỦ KẾT QUẢ KỲ</small><div class="number">${ks.filter(k=>score(k)!=null).length}/${ks.length}</div><p>${ks.length?Math.round(ks.filter(k=>score(k)!=null).length/ks.length*100):0}% hoàn thành nhập liệu</p></div><div class="card"><small>CẦN CHÚ Ý</small><div class="number">${ks.filter(k=>score(k)!=null&&score(k)<80).length}</div><p>Dưới 80% mục tiêu kỳ${overdueCount?` · ${overdueCount} việc quá hạn`:''}</p></div></div>${warning()}<div class="panels"><div class="panel"><div class="paneltitle"><h2>Điểm tổng hợp theo nhóm</h2><small>${esc(titlePeriod())}</small></div>${Object.values(groups).map(a=>{let n=totalScore(a,period),own=ownScore(a,period);return `<div class="progressrow"><span><strong>${esc(KPI.label(a))}</strong><small class="mini"><br>${esc(a[0].level)} · Điểm riêng: ${num(own)}%</small></span><div class="track"><div class="fill ${fillClass(n)}" style="width:${Math.min(100,n||0)}%"></div></div><strong>${num(n)}%</strong></div>`}).join('')||'<p>Hãy tạo KPI đầu tiên.</p>'}<p class="mini">Điểm tổng hợp kết hợp IID, Bộ phận và Cá nhân theo cơ cấu trọng số; chỉ tính khi nhóm đủ dữ liệu và tổng trọng số = 100%.</p></div><div class="panel"><h2>Nhịp quản trị & cảnh báo</h2>${ks.filter(k=>score(k)==null).length?`<div class="alert">${ks.filter(k=>score(k)==null).length} KPI chưa đủ kết quả trong ${esc(titlePeriod())}.</div>`:'<div class="alert ok">Tất cả KPI đã có dữ liệu trong kỳ.</div>'}${ks.filter(k=>score(k)!=null&&score(k)<80).map(k=>`<div class="alert"><strong>${esc(k.name)}</strong> (${esc(k.owner)}): đạt ${num(score(k))}% mục tiêu kỳ.</div>`).slice(0,3).join('')}<div class="alert">${state.actions.filter(a=>a.status!=='Hoàn tất').length} công việc đang mở${overdueCount?` (<strong>${overdueCount} việc quá hạn</strong>)`:''}.</div><p>Chọn Tháng để cập nhật số liệu; chọn Quý để rà soát và chốt đánh giá.</p><div class="flexbetween"><button onclick="view='review';render()">Đánh giá quý →</button><button onclick="view='actions';render()">Kế hoạch hành động →</button></div></div></div><div class="sectionspace">${rows(ks)}</div>`;
  if(view==='kpis'){
    let archived=state.archive||[];
    $('#app').innerHTML=head('Sổ KPI','Mục tiêu theo kỳ, email người được giao và kết quả dùng chung.',true)+warning()+`<div class="toolbar"><input id="search" placeholder="Tìm KPI, tên, email hoặc nguồn dữ liệu…"><select id="filterLevel"><option value="">Tất cả cấp</option><option>IID</option><option>Bộ phận</option><option>Cá nhân</option></select><select id="filterTeam"><option value="">Tất cả bộ phận</option>${[...new Set(ks.map(k=>k.team))].map(t=>`<option>${esc(t)}</option>`).join('')}</select><select id="filterStatus"><option value="">Tất cả trạng thái</option><option value="achieved">Đạt mục tiêu (≥100%)</option><option value="tracking">Đang theo dõi (80–99%)</option><option value="risk">Cần chú ý (&lt;80%)</option><option value="missing">Chưa đủ dữ liệu</option></select></div><div id="results"></div>`+(archived.length?`<div class="sectionspace"><div class="paneltitle"><h2>Kho lưu trữ KPI (${archived.length})</h2><button onclick="showArchive=!showArchive;render()">${showArchive?'Ẩn kho lưu trữ':'Xem KPI đã lưu trữ'}</button></div>${showArchive?`<div class="tablewrap"><table><thead><tr><th>KPI ĐÃ LƯU TRỮ</th><th>CẤP / BỘ PHẬN</th><th>TRỌNG SỐ</th><th>MỤC TIÊU NĂM</th><th>THỜI GIAN LƯU TRỮ</th><th>THAO TÁC</th></tr></thead><tbody>${archived.map(k=>`<tr><td><strong>${esc(k.name)}</strong><small>${esc(k.owner)} · ${esc(k.ownerEmail||'')}</small></td><td>${esc(k.level)}<small>${esc(k.team)}</small></td><td>${num(k.weight)}%</td><td>${num(k.target)} ${esc(k.unit)}</td><td>${k.archivedAt?esc(new Date(k.archivedAt).toLocaleString('vi-VN')):'—'}</td><td>${manage(k)?`<button onclick="restoreKpi(${JSON.stringify(k.id).replaceAll('"','&quot;')})">↺ Khôi phục</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:''}</div>`:'');
    let filter=()=>{let q=$('#search').value.toLowerCase(),lv=$('#filterLevel').value,tm=$('#filterTeam').value,st=$('#filterStatus').value;$('#results').innerHTML=rows(ks.filter(k=>{let s=score(k);return [k.name,k.owner,k.ownerEmail,k.team,k.source].join(' ').toLowerCase().includes(q)&&(!lv||k.level===lv)&&(!tm||k.team===tm)&&(!st||st==='achieved'&&s>=100||st==='tracking'&&s>=80&&s<100||st==='risk'&&s!=null&&s<80||st==='missing'&&s==null)}))};
    ['search','filterLevel','filterTeam','filterStatus'].forEach(id=>$('#'+id).oninput=filter);filter();
  }
  if(view==='cascade')renderCascadeView();
  if(view==='review'){
    let q=period.type==='quarter'?period.value:Math.ceil(period.value/3),p={type:'quarter',value:q};
    $('#app').innerHTML=head('Đánh giá quý '+q,'Dữ liệu cả quý được tổng hợp theo cách tính của từng KPI.')+`<div class="alert">Cộng / trung bình cần đủ 3 tháng (${KPI.months(q).map(m=>'T'+m).join(', ')}); giá trị cuối kỳ cần kết quả tháng ${q*3}. Chốt quý sẽ khóa cập nhật dữ liệu các tháng trong quý và lưu bản chụp (snapshot) kết quả tại thời điểm chốt.</div>`+Object.entries(groups).map(([key,a],i)=>{
      let r=state.reviews[q+'|'+key]||{},n=totalScore(a,p),own=ownScore(a,p),allowed=user.role==='admin'||user.role==='leader'&&a[0].level==='IID'||user.role==='manager'&&a[0].level!=='IID'&&a[0].team===user.team;
      let snapKpis=r.snapshot?.kpis||a.map(k=>({...k,result:KPI.measure(k,p)}));
      return `<div class="panel reviewcard"><div class="paneltitle"><div><h2>${esc(KPI.label(a))}</h2><p class="mini" style="margin:4px 0 0">${a.length} KPI · Điểm KPI riêng: <strong>${num(own)}%</strong> · Điểm tổng hợp: <strong>${num(r.snapshot?.score??n)}%</strong> · ${r.at?'Lưu lúc '+esc(new Date(r.at).toLocaleString('vi-VN'))+' bởi '+esc(r.by):'Chưa lưu đánh giá'}</p></div><div><span class="badge ${r.status==='Đã đánh giá'?'':'warn'}">${esc(r.status||'Nháp')} · ${num(r.snapshot?.score??n)}%</span></div></div><div class="subtable"><table><thead><tr><th>KPI TRONG NHÓM</th><th>CÁCH TÍNH QUÝ</th><th>TRỌNG SỐ</th><th>MỤC TIÊU QUÝ</th><th>THỰC TẾ QUÝ</th><th>HOÀN THÀNH</th></tr></thead><tbody>${snapKpis.map(k=>{let res=k.result||KPI.measure(k,p);return `<tr><td><strong>${esc(k.name)}</strong></td><td>${esc(modeNames[k.mode||'last'])}</td><td>${num(k.weight)}%</td><td>${num(res.target)} ${esc(k.unit)}</td><td>${num(res.actual)} ${res.actual!=null?esc(k.unit):''} <small style="display:inline">(${res.coverage}/${res.total} tháng)</small></td><td><span class="badge ${res.score==null?'warn':res.score<80?'bad':res.score<100?'warn':''}">${num(res.score)}%</span></td></tr>`}).join('')}</tbody></table></div><label>Nhận xét đánh giá & định hướng quý tiếp theo<textarea id="review${i}" rows="3" placeholder="Ghi nhận kết quả nổi bật, nguyên nhân chênh lệch và giải pháp cải thiện…" aria-label="Nhận xét ${esc(KPI.label(a))}" ${!allowed||r.status==='Đã đánh giá'?'disabled':''}>${esc(r.note||'')}</textarea></label><div class="flexbetween"><div>${allowed&&r.status!=='Đã đánh giá'?`<button onclick="reviewSave(${i},${q},'${encodeURIComponent(key).replaceAll("'","%27")}','Nháp')">Lưu nháp</button> <button class="primary" onclick="reviewSave(${i},${q},'${encodeURIComponent(key).replaceAll("'","%27")}','Đã đánh giá')">Chốt đánh giá</button>`:''}${r.status==='Đã đánh giá'&&user.role==='admin'?`<button onclick="reviewSave(${i},${q},'${encodeURIComponent(key).replaceAll("'","%27")}','Nháp')">Mở lại quý</button>`:''}</div>${user.role!=='viewer'?`<button onclick="quickActionFromReview(${JSON.stringify(a[0].team).replaceAll('"','&quot;')},${JSON.stringify(a[0].owner).replaceAll('"','&quot;')},${JSON.stringify(a[0].ownerEmail||user.email).replaceAll('"','&quot;')})">+ Tạo việc cần làm</button>`:''}</div></div>`;
    }).join('');
  }
  if(view==='trend'){
    $('#app').innerHTML=head('Tiến độ 12 tháng','So sánh kết quả từng tháng với mục tiêu đã phân bổ. Bấm vào ô tháng để cập nhật nhanh.')+`<div class="toolbar"><input id="trendSearch" placeholder="Tìm KPI hoặc người phụ trách…"><select id="trendLevel"><option value="">Tất cả cấp</option><option>IID</option><option>Bộ phận</option><option>Cá nhân</option></select><select id="trendTeam"><option value="">Tất cả bộ phận</option>${[...new Set(ks.map(k=>k.team))].map(t=>`<option>${esc(t)}</option>`).join('')}</select></div><div id="trendTable"></div>`;
    let renderTrend=()=>{
      let q=($('#trendSearch')?.value||'').toLowerCase(),lv=$('#trendLevel')?.value||'',tm=$('#trendTeam')?.value||'';
      let list=ks.filter(k=>[k.name,k.owner,k.team].join(' ').toLowerCase().includes(q)&&(!lv||k.level===lv)&&(!tm||k.team===tm));
      $('#trendTable').innerHTML=!list.length?'<div class="empty">Không có KPI phù hợp.</div>':`<div class="tablewrap"><table><thead><tr><th>KPI / PHÂN BỔ</th>${Array.from({length:12},(_,i)=>`<th>T${i+1}</th>`).join('')}</tr></thead><tbody>${list.map(k=>`<tr><td><strong>${esc(k.name)}</strong><small>${esc(k.owner)} · ${esc(modeNames[k.mode])}</small></td>${Array.from({length:12},(_,i)=>{let m=i+1,r=KPI.measure(k,{type:'month',value:m}),canClick=write(k);return `<td ${canClick?`style="cursor:pointer" title="Bấm để cập nhật Tháng ${m}" onclick="openUpdateMonth(${JSON.stringify(k.id).replaceAll('"','&quot;')},${m})"`:''}><span class="badge ${r.score==null?'neutral':r.score<80?'bad':r.score<100?'warn':''}">${num(r.score)}%</span><small>${num(r.actual)} / ${num(r.target)}</small></td>`}).join('')}</tr>`).join('')}</tbody></table></div>`;
    };
    ['trendSearch','trendLevel','trendTeam'].forEach(id=>$('#'+id).oninput=renderTrend);renderTrend();
  }
  if(view==='actions')renderActionsView();
  if(view==='guide')$('#app').innerHTML=head('Quy tắc & hướng dẫn','Quản trị KPI 2027 dùng chung trong khối IID.')+`<div class="guidegrid"><div class="panel"><h2>01 · Quyền thao tác & Bảo mật</h2><p><strong>Quản trị (Admin):</strong> Toàn bộ KPI, cơ cấu trọng số, tài khoản và chốt/mở lại quý.<br><strong>Cấp IID (Leader):</strong> Quản lý KPI cấp IID, đánh giá quý IID và kế hoạch hành động IID.<br><strong>Quản lý (Manager):</strong> KPI, kết quả, đánh giá và công việc thuộc bộ phận của mình.<br><strong>Nhân viên (Contributor):</strong> Cập nhật kết quả KPI và công việc giao đúng email của mình.<br><strong>Người xem (Viewer):</strong> Chỉ đọc trong phạm vi cấp được giao.</p></div><div class="panel"><h2>02 · Điểm & Dữ liệu kỳ</h2><p>Tháng đối chiếu với mục tiêu tháng (mặc định theo phân bổ hoặc đặt riêng từng tháng). Quý tổng hợp theo cấu hình KPI: <em>Giá trị cuối kỳ</em>, <em>Cộng 3 tháng</em> hoặc <em>Trung bình 3 tháng</em>. Nhóm thiếu dữ liệu bắt buộc hoặc tổng trọng số khác 100% sẽ chưa tính điểm. Trần điểm thành phần và tổng hợp là 120%.</p></div><div class="panel"><h2>03 · Liên kết 3 tầng & Trọng số</h2><p>Mục tiêu liên kết chặt chẽ từ <strong>IID → Bộ phận → Cá nhân</strong>. Cơ cấu điểm tổng hợp mặc định: Bộ phận (50% IID + 50% Bộ phận), Cá nhân (30% IID + 40% Bộ phận + 30% Cá nhân). Khi xóa KPI không còn dùng, hệ thống đưa vào <em>Kho lưu trữ</em> để bảo toàn lịch sử và có thể khôi phục khi cần.</p></div><div class="panel"><h2>04 · Dữ liệu dùng chung & Kiểm toán</h2><p>Mọi thay đổi lưu tập trung trên máy chủ với cơ chế kiểm soát phiên bản (chống ghi đè khi nhiều người cùng sửa). Nhật ký kiểm toán (Audit Log) ghi nhận đầy đủ người thực hiện, thao tác và thời gian. Có thể xuất bản sao JSON hoặc báo cáo CSV bất kỳ lúc nào.</p></div></div>`;
}
function renderCascadeNode(k,all,depth=0){
  let isVisible=state.kpis.some(x=>x.id===k.id),r=isVisible?result(k):null,children=all.filter(c=>c.parent===k.id);
  return `<div class="treeitem"><div class="cascaderow"><div><span class="badge ${depth===0?'':depth===1?'warn':'neutral'}">${esc(k.level)}</span> <strong>${esc(k.name)}</strong><small class="mini" style="display:block;margin-top:4px">${esc(k.team)}${k.owner?' · '+esc(k.owner):''}${k.weight!=null?' · Trọng số: '+num(k.weight)+'%':''}</small></div>${isVisible?`<div class="cascademeta"><span>${num(r.actual)} / ${num(r.target)} ${esc(k.unit)}</span><div class="track"><div class="fill ${fillClass(r.score)}" style="width:${Math.min(100,r.score||0)}%"></div></div><span class="badge ${r.score==null?'warn':r.score<80?'bad':r.score<100?'warn':''}">${num(r.score)}%</span></div>`:'<span class="badge neutral">Mục tiêu cấp trên liên kết</span>'}</div>${children.length?`<div class="tree">${children.map(c=>renderCascadeNode(c,all,depth+1)).join('')}</div>`:''}</div>`;
}
function renderCascadeView(){
  let all=[...(state.references||[]),...state.kpis],roots=all.filter(k=>k.level==='IID'||!k.parent||!all.some(p=>p.id===k.parent));
  $('#app').innerHTML=head('Liên kết mục tiêu','Kết nối xuyên suốt IID → Bộ phận → Cá nhân',true)+`<div class="panel"><h2>Cơ cấu điểm tổng hợp</h2><p class="mini">Điểm đánh giá của Bộ phận và Cá nhân là sự kết hợp giữa kết quả chung của Khối IID, Bộ phận và kết quả KPI trực tiếp theo tỷ lệ dưới đây.</p><div class="guidegrid">${mixForm('department','Cơ cấu cấp Bộ phận',['IID','Bộ phận'],[[30,70],[30,70]])}${mixForm('personal','Cơ cấu cấp Cá nhân',['IID','Bộ phận','Cá nhân'],[[20,40],[30,50],[20,40]])}</div></div><div class="sectionspace">${roots.map(r=>renderCascadeNode(r,all,0)).join('')||'<div class="empty">Chưa có KPI trong phạm vi.</div>'}</div>`;
}
function renderActionsView(){
  let can=user.role!=='viewer',acts=state.actions||[],openCount=acts.filter(a=>a.status!=='Hoàn tất').length,overCount=acts.filter(isOverdue).length,doneCount=acts.filter(a=>a.status==='Hoàn tất').length;
  let editObj=acts.find(a=>a.id===editingAction);
  $('#app').innerHTML=head('Kế hoạch hành động','Biến phản hồi đánh giá thành công việc cụ thể có người phụ trách, KPI liên kết và thời hạn.')+`<div class="stats"><div class="card"><small>TỔNG CÔNG VIỆC</small><div class="number">${acts.length}</div><p>Trong phạm vi hiển thị</p></div><div class="card"><small>ĐANG MỞ</small><div class="number">${openCount}</div><p>Mới hoặc đang thực hiện</p></div><div class="card"><small>QUÁ HẠN</small><div class="number" style="color:${overCount?'var(--bad)':'inherit'}">${overCount}</div><p>Cần ưu tiên xử lý</p></div><div class="card"><small>HOÀN TẤT</small><div class="number" style="color:var(--green)">${doneCount}</div><p>${acts.length?Math.round(doneCount/acts.length*100):0}% tỷ lệ hoàn thành</p></div></div>`+(can?`<form id="actionform" class="panel"><div class="paneltitle"><h2>${editObj?'Cập nhật công việc':'Thêm công việc mới'}</h2>${editObj?'<button type="button" onclick="editingAction=null;render()">Hủy sửa</button>':''}</div><div class="fields"><label>Việc cần làm<input name="title" required value="${esc(editObj?.title||'')}"></label><label>KPI liên quan<select name="kpiId"><option value="">— Chung / Không gắn KPI riêng —</option>${state.kpis.map(k=>`<option value="${esc(k.id)}" ${editObj?.kpiId===k.id?'selected':''}>${esc(k.name)} (${esc(k.team)})</option>`).join('')}</select></label><label>Người phụ trách<input name="owner" required value="${esc(editObj?.owner??(user.name||''))}"></label><label>Email phụ trách<input name="ownerEmail" type="email" required value="${esc(editObj?.ownerEmail??user.email)}"></label><label>Bộ phận<input name="team" required value="${esc(editObj?.team??(user.team||'Toàn khối'))}"></label><label>Cấp hành động<select name="level">${['IID','Bộ phận','Cá nhân'].filter(l=>user.role==='admin'||user.role==='leader'&&l==='IID'||user.role==='manager'&&l!=='IID'||user.role==='contributor'&&l==='Cá nhân').map(l=>`<option ${editObj?.level===l?'selected':''}>${l}</option>`).join('')}</select></label><label>Mức ưu tiên<select name="priority">${['Cao','Trung bình','Thấp'].map(p=>`<option ${(editObj?.priority||'Trung bình')===p?'selected':''}>${p}</option>`).join('')}</select></label><label>Hạn hoàn thành<input name="due" type="date" required value="${esc(editObj?.due||'')}"></label></div><label style="margin-top:12px">Ghi chú / Kết quả thực hiện<input name="note" value="${esc(editObj?.note||'')}" placeholder="Mô tả chi tiết hoặc link kết quả đầu ra…"></label><p style="margin:14px 0 0"><button class="primary">${editObj?'Lưu cập nhật':'+ Thêm việc cần làm'}</button></p></form>`:'')+`<div class="toolbar"><input id="actSearch" placeholder="Tìm công việc, người phụ trách hoặc bộ phận…"><select id="actStatus"><option value="">Tất cả trạng thái</option><option value="open">Đang mở (Mới & Đang làm)</option><option value="overdue">Quá hạn</option><option value="Mới">Mới</option><option value="Đang làm">Đang làm</option><option value="Hoàn tất">Hoàn tất</option></select><select id="actPriority"><option value="">Tất cả mức ưu tiên</option><option>Cao</option><option>Trung bình</option><option>Thấp</option></select></div><div id="actionList" class="sectionspace"></div>`;
  if(can)$('#actionform').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));let action={...editObj,...d,id:editObj?.id||crypto.randomUUID(),ownerEmail:d.ownerEmail.toLowerCase().trim(),status:editObj?.status||'Mới'};if(await mutate({type:'action',action})){editingAction=null;render()}};
  let filterActions=()=>{
    let q=($('#actSearch')?.value||'').toLowerCase(),st=$('#actStatus')?.value||'',pr=$('#actPriority')?.value||'';
    let list=acts.filter(a=>[a.title,a.owner,a.ownerEmail,a.team,a.note||''].join(' ').toLowerCase().includes(q)&&(!st||st==='open'&&a.status!=='Hoàn tất'||st==='overdue'&&isOverdue(a)||a.status===st)&&(!pr||(a.priority||'Trung bình')===pr));
    $('#actionList').innerHTML=!list.length?'<div class="empty">Không có công việc phù hợp.</div>':list.map(a=>{
      let canEdit=user.role==='admin'||user.role==='leader'&&a.level==='IID'||user.role==='manager'&&a.team===user.team&&a.level!=='IID'||user.role==='contributor'&&a.ownerEmail?.toLowerCase()===user.email;
      let linkedKpi=a.kpiId?state.kpis.find(k=>k.id===a.kpiId):null,overdue=isOverdue(a),prio=a.priority||'Trung bình';
      return `<div class="panel reviewcard"><div class="paneltitle"><h2>${esc(a.title)}</h2><div class="actionmeta"><span class="badge ${prio==='Cao'?'bad':prio==='Thấp'?'neutral':'warn'}">Ưu tiên: ${esc(prio)}</span>${overdue?'<span class="badge bad">Quá hạn</span>':''}<span class="badge ${a.status==='Hoàn tất'?'':a.status==='Đang làm'?'warn':'neutral'}">${esc(a.status)}</span></div></div><p style="margin:6px 0"><strong>${esc(a.owner)}</strong> (${esc(a.ownerEmail||'')}) · ${esc(a.team)} · Cấp ${esc(a.level||'Cá nhân')} · Hạn: <strong>${esc(a.due)}</strong>${linkedKpi?` · KPI: <strong>${esc(linkedKpi.name)}</strong>`:''}</p>${a.note?`<p class="mini" style="margin:6px 0">Ghi chú: ${esc(a.note)}</p>`:''}${canEdit?`<div style="margin-top:12px"><select aria-label="Trạng thái ${esc(a.title)}" onchange="changeAction('${encodeURIComponent(a.id).replaceAll("'","%27")}',this.value)">${['Mới','Đang làm','Hoàn tất'].map(s=>`<option ${s===a.status?'selected':''}>${s}</option>`).join('')}</select><button onclick="editingAction=${JSON.stringify(a.id).replaceAll('"','&quot;')};render();window.scrollTo({top:0,behavior:'smooth'})">Sửa</button> <button class="danger" onclick="deleteAction('${encodeURIComponent(a.id).replaceAll("'","%27")}')">Xóa</button></div>`:''}</div>`;
    }).join('');
  };
  ['actSearch','actStatus','actPriority'].forEach(id=>$('#'+id).oninput=filterActions);filterActions();
}
function quickActionFromReview(team,owner,ownerEmail){view='actions';editingAction=null;render();let f=$('#actionform');if(f){f.elements.team.value=team||'';f.elements.owner.value=owner||'';f.elements.ownerEmail.value=ownerEmail||user.email;f.elements.title.focus()}}
async function initialize(kind){let s;if(kind==='local'){try{s=JSON.parse(localStorage.getItem('iid-kpi-v1'));if(!s)throw Error()}catch{return toast('Trình duyệt này chưa có dữ liệu cũ. Hãy nhập file JSON hoặc dùng dữ liệu mẫu.')}}else s={kpis:kind==='sample'?seed:[],reviews:{},mix:{department:[50,50],personal:[30,40,30]}};try{KPI.validate(s);await mutate({type:'replace',state:KPI.migrate(s)})}catch(e){toast(e.message)}}
function updateWeightHint(){
  if(!state)return;let f=$('#form'),l=f.elements.level.value,tm=f.elements.team.value.trim(),ow=f.elements.owner.value.trim(),em=f.elements.ownerEmail.value.trim().toLowerCase();
  let probeKey=KPI.key({level:l,team:tm,owner:ow,ownerEmail:em});
  let others=state.kpis.filter(k=>k.id!==editing&&KPI.key(k)===probeKey);
  let sumOthers=others.reduce((s,k)=>s+k.weight,0),rem=Math.max(0,Math.round((100-sumOthers)*10)/10);
  $('#weighthint').textContent=`(Nhóm đã có ${num(sumOthers)}% · Còn lại ${num(rem)}%)`;
  return rem;
}
function parentOptions(){let f=$('#form'),l=f.elements.level.value;f.elements.parent.innerHTML='<option value="">Không có</option>'+[...state.kpis,...(state.references||[])].filter(k=>k.id!==editing&&l!=='IID'&&k.level===(l==='Cá nhân'?'Bộ phận':'IID')&&(l!=='Cá nhân'||k.team===f.elements.team.value)).map(k=>`<option value="${esc(k.id)}">${esc(k.name)} · ${esc(k.team)}</option>`).join('');f.elements.parent.required=l!=='IID';updateWeightHint()}
function openEditor(id){editing=id||null;$('#form').reset();let k=state.kpis.find(k=>k.id===id);$('#formtitle').textContent=k?'Sửa KPI':'Tạo KPI';if(k)for(let n of ['name','level','team','owner','ownerEmail','weight','target','unit','direction','source','frequency','mode','plan'])$('#form').elements[n].value=k[n]??'';else{if(user.role==='manager'){$('#form').elements.level.value='Bộ phận';$('#form').elements.team.value=user.team}else if(user.role==='leader'){$('#form').elements.level.value='IID';$('#form').elements.team.value='Toàn khối'}}parentOptions();if(k)$('#form').elements.parent.value=k.parent||'';else{let rem=updateWeightHint();if(rem>0&&rem<=100)$('#form').elements.weight.value=rem}$('#editor').showModal()}
['level','team','owner','ownerEmail'].forEach(n=>$('#form').elements[n].addEventListener('input',parentOptions));
$('#close').onclick=()=>$('#editor').close();$('#form').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target)),old=state.kpis.find(k=>k.id===editing);let k={...d,id:editing||crypto.randomUUID(),target:Number(d.target),weight:Number(d.weight),ownerEmail:d.ownerEmail.toLowerCase().trim(),parent:d.level==='IID'?null:d.parent,updates:old?.updates||{},targets:old?.targets||{}};if(await mutate({type:'kpi',kpi:k}))$('#editor').close()};
async function removeKpi(id){if(confirm('Lưu trữ KPI này vào kho lưu trữ? (KPI con nếu có cần được đổi liên kết trước)'))await mutate({type:'delete',id})}
async function restoreKpi(id){await mutate({type:'restore',id})}
function openUpdateMonth(id,m){period={type:'month',value:m};$('#periodType').value='month';periodOptions();render();openUpdate(id)}
function openUpdate(id){if(period.type!=='month'){period={type:'month',value:(period.value-1)*3+1};$('#periodType').value='month';periodOptions();render()}updating=id;let k=state.kpis.find(k=>k.id===id),u=k.updates[period.value],f=$('#updateform');f.reset();$('#updatename').textContent=`${k.name} · ${titlePeriod()} · Đơn vị: ${k.unit} (${modeNames[k.mode]})`;$('#updatehistory').innerHTML=Array.from({length:12},(_,i)=>{let m=i+1,r=KPI.measure(k,{type:'month',value:m});return `<div class="monthcell ${m===period.value?'active':''}" onclick="openUpdateMonth(${JSON.stringify(k.id).replaceAll('"','&quot;')},${m})">T${m}<small>${num(r.actual)}/${num(r.target)}</small></div>`}).join('');f.elements.actual.value=u?.actual??'';f.elements.note.value=u?.note||'';f.elements.periodTarget.value=k.targets[period.value]??'';f.elements.periodTarget.disabled=!manage(k);$('#update').showModal()}
$('#updateform').onsubmit=async e=>{e.preventDefault();let f=e.target,k=state.kpis.find(k=>k.id===updating);if(manage(k)){let value=f.elements.periodTarget.value;let targets={...k.targets};if(value==='')delete targets[period.value];else targets[period.value]=Number(value);if(JSON.stringify(targets)!==JSON.stringify(k.targets)){if(!await mutate({type:'kpi',kpi:{...k,targets}}))return}}if(await mutate({type:'update',id:updating,month:period.value,actual:Number(f.elements.actual.value),note:f.elements.note.value}))$('#update').close()};
function mixForm(key,title,labels,bounds){return `<form onsubmit="saveMix(event,'${key}')"><h3>${title}</h3>${labels.map((l,i)=>`<label>${l} (${bounds[i][0]}–${bounds[i][1]}%)<input name="v${i}" type="number" min="${bounds[i][0]}" max="${bounds[i][1]}" value="${state.mix[key][i]}" required ${user.role!=='admin'?'disabled':''}></label>`).join('')}${user.role==='admin'?'<p style="margin:12px 0 0"><button>Lưu cơ cấu</button></p>':''}</form>`}
async function saveMix(e,key){e.preventDefault();let mix={...state.mix,[key]:[...new FormData(e.target).values()].map(Number)};try{KPI.validate({...state,mix});await mutate({type:'mix',mix})}catch(e){toast(e.message)}}
async function reviewSave(i,q,key,status){if(status==='Đã đánh giá'&&!confirm('Chốt đánh giá và khóa dữ liệu quý này?'))return;await mutate({type:'review',quarter:q,group:decodeURIComponent(key),note:$('#review'+i).value,status})}
async function changeAction(id,status){let a=state.actions.find(a=>a.id===decodeURIComponent(id));await mutate({type:'action',action:{...a,status}})}
async function deleteAction(id){if(!confirm('Xóa công việc này khỏi kế hoạch hành động?'))return;await mutate({type:'delete_action',id:decodeURIComponent(id)})}
function periodOptions(){let count=period.type==='month'?12:4;$('#month').innerHTML=Array.from({length:count},(_,i)=>`<option value="${i+1}" ${i+1===period.value?'selected':''}>${period.type==='month'?'Tháng':'Quý'} ${i+1} / 2027</option>`).join('')}
$('#periodType').onchange=e=>{period={type:e.target.value,value:e.target.value==='quarter'?Math.ceil(period.value/3):period.value*3};periodOptions();render()};$('#month').onchange=e=>{period.value=Number(e.target.value);render()};$('#refresh').onclick=sync;document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});
function download(text,type,name){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}$('#backup').onclick=()=>{if(state)download(JSON.stringify(state,null,2),'application/json','iid-kpi-shared-2027.json')};$('#export').onclick=()=>{if(!state)return;let cell=v=>'"'+String(v??'').replaceAll('"','""').replace(/^[=+@\-]/,"'$&")+'"';download('\ufeff'+[['KPI','Cấp','Bộ phận','Owner','Email','Trọng số','Kỳ','Mục tiêu kỳ','Thực tế','Điểm %','Nguồn','Ghi chú'],...state.kpis.map(k=>{let r=result(k);return[k.name,k.level,k.team,k.owner,k.ownerEmail,k.weight,titlePeriod(),r.target,r.actual,r.score,k.source,period.type==='month'?k.updates[period.value]?.note||'':'']})].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8','iid-kpi-report.csv')};
$('#import').onchange=async e=>{try{if(user.role!=='admin')throw Error('Chỉ quản trị được nhập dữ liệu.');let s=JSON.parse(await e.target.files[0].text());KPI.validate(s);if(confirm('Thay dữ liệu kho chung bằng bản sao? Hãy xuất bản sao hiện tại trước.'))await mutate({type:'replace',state:KPI.migrate(s)})}catch(e){toast(e.message)}finally{e.target.value=''}};



